{
  "name": "SHFQA量子分析仪读出模块",
  "name_en": "SHFQA Quantum Analyzer Readout Module",
  "manufacturer": "Zurich Instruments",
  "description": "用于苏黎世仪器 SHFQA 量子分析仪的读出功能模块，面向量子比特/多能级态测量。它可配置结果记录器、写入和读取加权积分权重、运行读出采集，并管理与测序器、波形存储器和触发相关的读出流程。",
  "description_en": "A readout functional module for the Zurich Instruments SHFQA quantum analyzer, intended for qubit and multistate measurement. It configures the result logger, writes and reads weighted integration weights, runs readout acquisition, and manages readout-related sequencer, waveform memory, and trigger operations.",
  "actions": [
    {
      "action_name": "auto-configure_result_logger",
      "description": "配置读出模式的结果记录器。",
      "description_en": "Configure the result logger for readout mode."
    },
    {
      "action_name": "auto-read",
      "description": "等待结果记录完成并读取测量数据。",
      "description_en": "Wait for the result logger to finish and read the measured data."
    },
    {
      "action_name": "auto-read_integration_weights",
      "description": "从设备读取积分权重。",
      "description_en": "Read integration weights from the device."
    },
    {
      "action_name": "auto-run",
      "description": "重置并启用结果记录器，开始读出记录。",
      "description_en": "Reset and enable the result logger to start readout logging."
    },
    {
      "action_name": "auto-stop",
      "description": "停止结果记录器。",
      "description_en": "Stop the result logger."
    },
    {
      "action_name": "auto-wait_done",
      "description": "等待读出过程完成。",
      "description_en": "Wait until the readout operation is finished."
    },
    {
      "action_name": "auto-write_integration_weights",
      "description": "写入加权积分权重并配置积分延迟等参数。",
      "description_en": "Write weighted integration weights and configure parameters such as integration delay."
    },
    {
      "action_name": "auto-enable_sequencer",
      "description": "启用通道测序器。",
      "description_en": "Enable the channel sequencer."
    },
    {
      "action_name": "auto-compile_sequencer_program",
      "description": "编译测序器程序。",
      "description_en": "Compile a sequencer program."
    },
    {
      "action_name": "auto-load_sequencer_program",
      "description": "将测序器程序加载到设备。",
      "description_en": "Load a sequencer program onto the device."
    },
    {
      "action_name": "auto-write_to_waveform_memory",
      "description": "将波形写入设备的波形存储器。",
      "description_en": "Write waveforms to the device waveform memory."
    },
    {
      "action_name": "auto-read_from_waveform_memory",
      "description": "从设备的波形存储器读取波形数据。",
      "description_en": "Read waveform data from the device waveform memory."
    },
    {
      "action_name": "auto-configure_sequencer_triggering",
      "description": "配置测序器触发方式。",
      "description_en": "Configure sequencer triggering."
    },
    {
      "action_name": "auto-available_aux_trigger_inputs",
      "description": "查询可用的辅助触发输入。",
      "description_en": "Query the available auxiliary trigger inputs."
    },
    {
      "action_name": "auto-configure",
      "description": "配置读出节点或相关测量功能的基本参数。",
      "description_en": "Configure the basic parameters of the readout node or related measurement functionality."
    },
    {
      "action_name": "auto-get_qudits_results",
      "description": "获取各个 qudit 的读出结果。",
      "description_en": "Get the readout results for the qudits."
    },
    {
      "action_name": "auto-configure_channel",
      "description": "配置 SHFQA 的 QA 通道参数。",
      "description_en": "Configure the QA channel settings of the SHFQA."
    },
    {
      "action_name": "auto-available_trigger_inputs",
      "description": "查询可用的触发输入。",
      "description_en": "Query the available trigger inputs."
    },
    {
      "action_name": "auto-available_inputs",
      "description": "查询可用的信号输入。",
      "description_en": "Query the available signal inputs."
    },
    {
      "action_name": "auto-factory_reset",
      "description": "将设备恢复为出厂设置。",
      "description_en": "Restore the device to factory settings."
    },
    {
      "action_name": "auto-start_continuous_sw_trigger",
      "description": "启动连续软件触发。",
      "description_en": "Start continuous software triggering."
    },
    {
      "action_name": "auto-max_qubits_per_channel",
      "description": "获取每个通道支持的最大 qubit 数量。",
      "description_en": "Get the maximum number of qubits supported per channel."
    }
  ],
  "tag_hints": [
    "quantum readout",
    "weighted integration",
    "result logger",
    "SHFQA",
    "qubit measurement",
    "sequencer control",
    "trigger configuration"
  ]
}

